"""Bounded, explicitly synthetic purchase-intent cohort generated by MiroFish.

The model creates every workshop profile and every forced-choice response. The
backend supplies opaque row IDs and verifies the exact cohort before reporting
counts. No row is a real interview or a market estimate.
"""

from __future__ import annotations

from collections import Counter
from typing import Any, Callable


COHORT_SIZE = 1000
BATCH_SIZE = 25
REASON_CODES = (
    "precio", "funciones", "confianza", "cfdi", "soporte",
    "exportacion", "cambio_de_habitos", "falta_info", "otro",
)


class CohortValidationError(ValueError):
    """A model batch or saved checkpoint cannot form a trustworthy cohort."""


def validate_scenario(scenario: Any) -> str:
    if not isinstance(scenario, str):
        raise CohortValidationError("scenario must be text")
    scenario = scenario.strip()
    if not 100 <= len(scenario) <= 8000:
        raise CohortValidationError("scenario must contain 100 to 8000 characters")
    return scenario


def row_id(number: int) -> str:
    return f"T{number:04d}"


def _short_text(value: Any, field: str, maximum: int) -> str:
    if not isinstance(value, str):
        raise CohortValidationError(f"{field} must be text")
    result = value.strip()
    if not result or len(result) > maximum:
        raise CohortValidationError(f"{field} must contain 1 to {maximum} characters")
    return result


def validate_batch(payload: Any, expected_ids: list[str]) -> list[dict[str, Any]]:
    """Accept exactly one complete, unique model response for each requested ID."""
    if not isinstance(payload, dict) or not isinstance(payload.get("rows"), list):
        raise CohortValidationError("model response must contain a rows array")
    raw_rows = payload["rows"]
    if len(raw_rows) != len(expected_ids):
        raise CohortValidationError("model response has the wrong number of rows")
    seen: set[str] = set()
    result: list[dict[str, Any]] = []
    allowed = set(REASON_CODES)
    for raw in raw_rows:
        if not isinstance(raw, dict):
            raise CohortValidationError("each row must be an object")
        identifier = raw.get("id")
        if not isinstance(identifier, str) or identifier not in expected_ids or identifier in seen:
            raise CohortValidationError("model response has a missing, unknown or duplicate ID")
        seen.add(identifier)
        workers = raw.get("workers")
        if type(workers) is not int or not 1 <= workers <= 50:
            raise CohortValidationError("workers must be an integer from 1 to 50")
        decision = raw.get("decision")
        if decision not in ("si", "no"):
            raise CohortValidationError("decision must be si or no")
        reason_code = raw.get("reason_code")
        if reason_code not in allowed:
            raise CohortValidationError("unknown reason code")
        result.append({
            "id": identifier,
            "workers": workers,
            "current_process": _short_text(raw.get("current_process"), "current_process", 80),
            "main_need": _short_text(raw.get("main_need"), "main_need", 120),
            "decision": decision,
            "reason_code": reason_code,
            "reason": _short_text(raw.get("reason"), "reason", 180),
        })
    if seen != set(expected_ids):
        raise CohortValidationError("model response omitted requested IDs")
    return sorted(result, key=lambda item: item["id"])


def _prompt(scenario: str, ids: list[str], batch_number: int) -> list[dict[str, str]]:
    codes = ", ".join(REASON_CODES)
    return [
        {"role": "system", "content": (
            "Eres el motor de una simulación SINTÉTICA de MiroFish. "
            "Genera tú mismo un taller de reparación de vehículos ficticio para cada ID y "
            "decide si compraría AHORA o no la propuesta, como elección forzada e hipotética. "
            "Si necesitaría aclaraciones antes de comprar, responde 'no' por ahora y usa falta_info. "
            "No uses ni alegues entrevistas, clientes o datos de mercado reales. "
            "No añadas porcentajes ni conclusiones sobre demanda real. "
            "La salida debe ser exactamente un objeto JSON con una sola clave: rows."
        )},
        {"role": "user", "content": (
            f"Escenario:\n{scenario}\n\n"
            f"Lote {batch_number} de {COHORT_SIZE // BATCH_SIZE}. "
            f"Genera exactamente {len(ids)} perfiles distintos con estos IDs, una fila por ID: "
            + ", ".join(ids) + ".\n"
            "Devuelve un objeto JSON con una sola clave rows (array). Cada fila debe tener: "
            "id, workers (entero 1-50), current_process (método actual de trabajo), "
            "main_need (necesidad principal), decision (exactamente 'si' o 'no' a "
            "la pregunta: con la información disponible, ¿compraría ahora la licencia?), "
            f"reason_code (uno de: {codes}) y reason (motivo breve, concreto). "
            "Todos los rasgos y las decisiones deben ser creados por ti para cada taller. "
            "No repitas IDs, no omitas ninguno, no inventes otros. No uses nombres de empresas reales. "
            "Empieza exactamente con {\"rows\":[ y termina con ]}; no incluyas título, resumen ni Markdown."
        )},
    ]


def generate_cohort(
    scenario: str,
    ask_model: Callable[[list[dict[str, str]]], dict[str, Any]],
    *,
    existing_rows: list[dict[str, Any]] | None = None,
    on_batch: Callable[[list[dict[str, Any]]], None] | None = None,
) -> dict[str, Any]:
    """Generate at most 40 batches, with no automatic model retries.

    A completed batch is checkpointed before asking for the next one. Resume
    accepts only whole, correctly ordered batches; a partial or forged result
    fails instead of being counted as a thousand answers.
    """
    scenario = validate_scenario(scenario)
    rows = list(existing_rows or [])
    if len(rows) > COHORT_SIZE or len(rows) % BATCH_SIZE:
        raise CohortValidationError("checkpoint must contain complete batches")
    for offset in range(0, len(rows), BATCH_SIZE):
        ids = [row_id(number) for number in range(offset + 1, offset + BATCH_SIZE + 1)]
        if validate_batch({"rows": rows[offset:offset + BATCH_SIZE]}, ids) != rows[offset:offset + BATCH_SIZE]:
            raise CohortValidationError("checkpoint rows are not canonical")
    for offset in range(len(rows), COHORT_SIZE, BATCH_SIZE):
        ids = [row_id(number) for number in range(offset + 1, offset + BATCH_SIZE + 1)]
        payload = ask_model(_prompt(scenario, ids, offset // BATCH_SIZE + 1))
        batch = validate_batch(payload, ids)
        rows.extend(batch)
        if on_batch is not None:
            on_batch(list(rows))
    if len(rows) != COHORT_SIZE or len({row["id"] for row in rows}) != COHORT_SIZE:
        raise CohortValidationError("cohort is incomplete")
    decisions = Counter(row["decision"] for row in rows)
    profile_patterns = {
        (row["workers"], row["current_process"].casefold(), row["main_need"].casefold())
        for row in rows
    }
    reasons = {
        decision: dict(sorted(Counter(
            row["reason_code"] for row in rows if row["decision"] == decision
        ).items()))
        for decision in ("si", "no")
    }
    return {
        "kind": "mirofish_synthetic_purchase_intent",
        "synthetic": True,
        "representative_sample": False,
        "method": "1000 fictitious workshop profiles and forced buy-now yes/no decisions generated by the MiroFish LLM in 40 validated batches",
        "fictional_workshops": COHORT_SIZE,
        "unique_profile_patterns": len(profile_patterns),
        "counts": {"si": decisions["si"], "no": decisions["no"]},
        "reason_counts": reasons,
        "rows": rows,
        "limitations": [
            "No workshop, owner or answer in this report is real.",
            "The forced choices are model role-play, not a survey or a sales forecast.",
            "The cohort has no measured distribution of workshop characteristics.",
            "Some fictional profiles may share the same recorded characteristics.",
            "The yes/no proportion depends on the prompt and model, not measured demand.",
        ],
    }
